    assert to_html("Hello < World") == "<p>Hello &lt; World</p>"
    assert to_html("Hello > World") == "<p>Hello &gt; World</p>"
    assert to_html("Hello & < > World") == "<p>Hello &amp; &lt; &gt; World</p>"

