                } else if (expr[i] === '-' && i > 0) {
                    let left = getNumber(expr, i - 1, true);
                    let right = getNumber(expr, i + 1, false);
                    let result = left - right;
                    expr = expr.substring(0, i - left.toString().length) + result + expr.substring(i + right.toString().length + 1);
                } else {
