    const firstRowLength = rows[0].length;
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      if (!Array.isArray(row)) {
        throw new Error("All rows must be arrays");
      }
      if (row.length !== firstRowLength) {
