        'ip': ip,
        'time': time,
        'method': method,
        'path': path,
        'status': status,
        'bytes': bytes_val,
        'seconds': seconds
    }

def parse_log(text):
    """Parse log text and return list of valid parsed dictionaries."""
    lines = text.strip().split('\n')
    result = []
    
    for line in lines:
        if not line.strip():  # Skip blank lines
            continue
        try:
            parsed = parse_line(line)
            result.append(parsed)
        except ValueError:
            # Skip malformed lines
            continue
    
    return result

