    counts = {}
    for entry in entries:
        status = entry['status']
        if status in counts:
            counts[status] += 1
        else:
            counts[status] = 1
    return counts

def error_rate(entries):
    """Return the fraction of entries whose status is 500 or more, rounded to 4 decimals.
