    // Check if all entries differ by at most eps
    for (let i = 0; i < thisShape[0]; i++) {
      for (let j = 0; j < thisShape[1]; j++) {
        if (Math.abs(this.get(i, j) - other.get(i, j)) > eps) {
          return false;
        }
      }
    }
    
    return true;
  }
}

module.exports = { Matrix };

