    }
    
    // Check if shapes match
    const thisShape = this.shape();
    const otherShape = other.shape();
    if (thisShape[0] !== otherShape[0] || thisShape[1] !== otherShape[1]) {
      throw new Error("Matrix shapes must match for subtraction");
    }
    
