                    }
                    start--;
                }
                start++;
            } else {
                // Get number to the right
                while (end < expr.length && (/\d/.test(expr[end]) || expr[end] === '.')) {
                    end++;
                }
            }
            
            // Check if this is a variable name
            if (start < end && /[A-Za-z_]/.test(expr[start])) {
